package com.molagpt.app.core.model

// Models.dev models.json, 2026-11-26, 647 canonical models; SHA-256 e6abdc013bb960e7a02e0cdd75c1dbc6c18997dbb3e5f637f55d29060ff2a409.
// Aliases and native effort vocabularies: locally cached Models.dev api.json; conflicting aliases/options omitted.
// Offline discovery fallback only. Explicit endpoint metadata and user settings take precedence.
data class KnownModelCapability(
    val canonicalId: String,
    private val flags: Int,
    val nativeEfforts: List<String>,
) {
    val reasoning get() = flags and 1 != 0
    val vision get() = flags and 2 != 0
    val tools get() = flags and 4 != 0
    val chat get() = flags and 8 != 0
    val image get() = flags and 16 != 0
}

object ModelCapabilityCatalog {
    private val entries: Map<String, KnownModelCapability> by lazy {
        buildMap {
            for (chunk in snapshot) for (line in chunk.lineSequence()) {
                if (line.isBlank()) continue
                val fields = line.split('|')
                val model = KnownModelCapability(fields[0], fields[1].toInt(),
                    fields[2].split(',').filter { it.isNotEmpty() })
                put(fields[0], model)
                for (alias in fields[3].split(',')) if (alias.isNotEmpty()) put(alias, model)
            }
        }
    }

    fun find(id: String): KnownModelCapability? {
        val key = id.trim().lowercase().removePrefix("models/")
        return entries[key] ?: entries[key.removeSuffix(":free")]
    }

